tool_input.command:
$repo='D:\repository\skills'; $inst='C:\Users\Administrator\.dsh\skills'
$repoSkills=@(Get-ChildItem -Path $repo -Directory -ErrorAction SilentlyContinue | Where-Object { Test-Path (Join-Path $_.FullName 'SKILL.md') } | Select-Object -ExpandProperty Name)
$instItems=@(Get-ChildItem -Path $inst -Force -ErrorAction SilentlyContinue)
Write-Output ("REPO_SKILLS(" + $repoSkills.Count + "): " + ($repoSkills -join ', '))
Write-Output '--- INSTALLED ---'
$instItems | ForEach-Object {
  $tg = if($_.LinkType){ (($_.Target) -join '|') } else {'-'}
  $ok = if($_.LinkType){ (Test-Path $_.FullName) } else {'n/a'}
  $sm = Test-Path (Join-Path $_.FullName 'SKILL.md')
  Write-Output ("{0}`t{1}`t{2}`tvalid={3}`tSKILL={4}" -f $_.Name, $(if($_.LinkType){$_.LinkType}else{'DIR'}), $tg, $ok, $sm)
}
Write-Output '--- MISSING (repo SKILL.md, not installed) ---'
$repoSkills | Where-Object { $instItems.Name -notcontains $_ }
Write-Output '--- NON-LINK installed dirs (possible stale copies) ---'
$instItems | Where-Object { -not $_.LinkType -and $_.PSIsContainer } | Select-Object -ExpandProperty Name

$inst='C:\Users\Administrator\.dsh\skills'; $repo='D:\repository\skills'
foreach($n in 'cursor-model-routing','vite-build-profiler','openviking-autostart'){
  $link=Join-Path $inst $n; $src=Join-Path $repo $n
  if(Test-Path $link){ Write-Output "SKIP exists: $n" } else { New-Item -ItemType Junction -Path $link -Target $src | Out-Null; Write-Output "CREATED: $n -> $src" }
}
$c=Join-Path $inst 'clarify-first'; $r=Join-Path $repo 'clarify-first'
if(Test-Path $c){
  $items=@(Get-ChildItem $c -Force); $repoItems=@(Get-ChildItem $r -Force)
  $same=($items.Count -eq $repoItems.Count) -and ((Get-FileHash (Join-Path $c 'SKILL.md') -Algorithm SHA256).Hash -eq (Get-FileHash (Join-Path $r 'SKILL.md') -Algorithm SHA256).Hash)
  if($c -eq 'C:\Users\Administrator\.dsh\skills\clarify-first' -and $same){
    Remove-Item -LiteralPath $c -Recurse -Force
    New-Item -ItemType Junction -Path $c -Target $r | Out-Null
    Write-Output 'CONVERTED: clarify-first -> Junction'
  } else { Write-Output "ABORT clarify-first: path or hash check failed (same=$same)" }
}
Write-Output '=== VERIFY ==='
foreach($n in 'cursor-model-routing','vite-build-profiler','openviking-autostart','clarify-first','session-handoff'){
  $i=Get-Item (Join-Path $inst $n) -ErrorAction SilentlyContinue
  Write-Output ("{0}`t{1}`tvalid={2}`tSKILL={3}" -f $n,$(if($i.LinkType){$i.LinkType}else{'DIR'}),(Test-Path $i.FullName),(Test-Path (Join-Path $i.FullName 'SKILL.md')))
}
